import React, { useEffect, useRef, useState } from 'react';
import { Button } from '@linm-soft-org/linm-web-common-components';
import styles from './MonthlyReportListRowMenu.module.css';

export type MonthlyReportRowAction = 'view';

interface Props {
  onAction: (action: MonthlyReportRowAction) => void;
  disabled?: boolean;
}

export const MonthlyReportListRowMenu: React.FC<Props> = ({ onAction, disabled = false }) => {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const close = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, [open]);

  if (disabled) return null;

  return (
    <div
      ref={rootRef}
      className={styles.root}
      onClick={(e) => e.stopPropagation()}
    >
      <Button
        variant="secondary"
        size="sm"
        aria-label="Thao tác dòng"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
        data-testid="monthly-report-row-menu-trigger"
      >
        <i className="fas fa-ellipsis-v" />
      </Button>
      {open && (
        <div className={styles.menu} role="menu">
          <button
            type="button"
            className={styles.menuItem}
            role="menuitem"
            onClick={() => {
              setOpen(false);
              onAction('view');
            }}
            data-testid="monthly-report-row-menu-view"
          >
            <i className="fas fa-eye" /> Xem / Sửa
          </button>
        </div>
      )}
    </div>
  );
};
